import {uid} from './model.js';
import {AUTOTILE_INDEX} from './vendor/rgss-autotile/table.js';
function imageEntry(entries,folder,name){const wanted=name.replace(/\.png$/i,'').toLowerCase();const matches=[...entries].filter(([p])=>p.replace(/\\/g,'/').toLowerCase().endsWith('/'+folder.toLowerCase()+'/'+wanted+'.png')||p.toLowerCase()===wanted+'.png');if(matches.length!==1)throw Error((matches.length?'Ambiguous':'Missing')+' '+folder+' image: '+name+'.png');return matches[0][1];}
async function image(bytes){const blob=new Blob([bytes],{type:'image/png'});if(typeof createImageBitmap==='function')return createImageBitmap(blob);const url=URL.createObjectURL(blob);try{return await new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve(im);im.onerror=()=>reject(Error('Could not decode a source PNG.'));im.src=url;});}finally{URL.revokeObjectURL(url);}}
export async function makeCartographerAtlas(tileset,patterns,entries){
 const sheet=await image(imageEntry(entries,'Tilesets',tileset.tileset_name)),autotiles=new Map(),bitmaps=[sheet];
 try{if(sheet.width!==256||sheet.height%32||sheet.height>32768)throw Error('Use a 256-pixel-wide RPG Maker XP tileset with complete 32-pixel rows.');
 for(const ids of patterns)for(const id of ids)if(id>0&&id<384){if(id<48)throw Error('Reserved RPG Maker tile ID '+id+' cannot be rendered.');const slot=Math.floor(id/48)-1;if(!autotiles.has(slot)){const name=tileset.autotile_names?.[slot];if(!name)throw Error('Autotile slot '+(slot+1)+' has no image.');const im=await image(imageEntry(entries,'Autotiles',name));if(im.width!==32&&(!(im.width%96===0)||im.height!==128))throw Error('Unsupported autotile dimensions: '+name);autotiles.set(slot,im);bitmaps.push(im);}}
 const keys=new Map();for(const ids of patterns){const lower=ids.filter(id=>id&&tileset.priorities[id]===0),upper=ids.map((id,z)=>({id,z})).filter(o=>o.id&&tileset.priorities[o.id]>0).sort((a,b)=>tileset.priorities[a.id]-tileset.priorities[b.id]||a.z-b.z).map(o=>o.id);for(const [kind,stack]of[['lower',lower],['upper',upper]])if(kind==='lower'||stack.length)keys.set(kind+':'+stack.join(','),{kind,stack});}
 const count=keys.size,width=256,height=Math.max(16,Math.ceil(count/16)*16);if(height>16384||width*height>32000000)throw Error('The converted tileset is too large. Use fewer source tiles.');const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;const assetId='cartographer-'+uid(),cells=new Map();let index=0;
 for(const[key,{kind,stack}]of keys){const x=index%16*16,y=Math.floor(index/16)*16;index++;if(kind==='lower'){c.fillStyle='#000000';c.fillRect(x,y,16,16);}for(const id of stack){if(id>=384){const n=id-384,sx=n%8*32,sy=Math.floor(n/8)*32;if(sy+32>sheet.height)throw Error('Tile '+id+' lies outside '+tileset.tileset_name);c.drawImage(sheet,sx,sy,32,32,x,y,16,16);}else{const im=autotiles.get(Math.floor(id/48)-1);if(im.width===32){c.drawImage(im,0,0,32,32,x,y,16,16);continue;}for(let q=0;q<4;q++){const n=AUTOTILE_INDEX[(id%48)*4+q];c.drawImage(im,n%6*16,Math.floor(n/6)*16,16,16,x+q%2*8,y+Math.floor(q/2)*8,8,8);}}}cells.set(key,{a:assetId,sx:x,sy:y,size:16});}
 const planes=new Map();for(const ids of patterns){const lower=ids.filter(id=>id&&tileset.priorities[id]===0),upper=ids.map((id,z)=>({id,z})).filter(o=>o.id&&tileset.priorities[o.id]>0).sort((a,b)=>tileset.priorities[a.id]-tileset.priorities[b.id]||a.z-b.z).map(o=>o.id);planes.set(ids.join(','),{lower:cells.get('lower:'+lower.join(',')),upper:upper.length?cells.get('upper:'+upper.join(',')):null});}
 const data=canvas.toDataURL('image/png');canvas.width=canvas.height=1;return{asset:{id:assetId,name:'Cartographer · '+tileset.tileset_name,width,height,tileSize:16,data},planes};
 }finally{for(const im of bitmaps)im.close?.();}
}
